style:
:root{--bg:#14161a;--card:#1e2127;--fg:#e6e8eb;--mut:#9aa3ad;--acc:#5c96c2;--line:#2c313a}
*{box-sizing:border-box}
body,.wrap{margin:0}
.wrap{max-width:1400px;margin:0 auto;padding:24px;font:15px/1.55 system-ui,Segoe UI,sans-serif;color:var(--fg);background:var(--bg)}
h1{font-size:28px;margin:0 0 6px}
.lede{color:var(--mut);max-width:900px}
.toc{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:10px 14px;margin:16px 0 28px;font-size:14px}
.toc a{color:var(--acc);text-decoration:none;margin-right:6px}
.toc a:hover{text-decoration:underline}
section{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:20px 22px;margin:0 0 26px}
h2{font-size:21px;margin:0 0 10px;border-bottom:1px solid var(--line);padding-bottom:8px}
.what{margin:0 0 12px;max-width:1000px}
table.meta{border-collapse:collapse;margin:0 0 10px;font-size:14px}
table.meta th{text-align:right;color:var(--mut);font-weight:600;padding:2px 10px 2px 0;vertical-align:top;white-space:nowrap}
table.meta td{padding:2px 0}
code{background:#0e1013;border:1px solid var(--line);border-radius:4px;padding:1px 6px;color:#d7e3ee}
.note{background:#241f14;border-left:3px solid #b8892b;padding:8px 12px;border-radius:4px;color:#e8dcc0;font-size:14px;margin:10px 0}
.pl{font-weight:600;margin:18px 0 6px;color:#cfd6dd}
.ba{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.single{max-width:100%}
figure{margin:0}
figcaption{font-size:12px;color:var(--mut);margin-bottom:4px;text-transform:uppercase;letter-spacing:.04em}
img{width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:6px;background:#000}
a img:hover{border-color:var(--acc)}
.sev{font-size:11px;padding:1px 7px;border-radius:10px;text-transform:uppercase;letter-spacing:.03em}
.sev-high{background:#4a2020;color:#f0a0a0}
.sev-med{background:#40381c;color:#e0c878}
@media(max-width:720px){.ba{grid-template-columns:1fr}}
